#!/usr/bin/env bash
# Regenerates sqlite.sql / postgres.sql from a real padmark v0.1.6 binary.
# See README.md in this directory for the full procedure and the recorded scenario.
#
# Usage: generate.sh <path-to-v0.1.6-padmark-server> <sqlite|postgres> <output.sql>
#
# Requires: curl, jq, sqlite3 (sqlite), docker (postgres).
set -euo pipefail

bin=$1
storage=$2
out=$3
port=${PADMARK_FIXTURE_PORT:-18716}
base="http://127.0.0.1:${port}"
work=$(mktemp -d)
pg_container=padmark-v016-fixture
server_pid=""

cleanup() {
	if [[ -n $server_pid ]]; then kill "$server_pid" 2>/dev/null || true; fi
	if [[ $storage == postgres ]]; then docker rm -f "$pg_container" >/dev/null 2>&1 || true; fi
}
trap cleanup EXIT

case $storage in
sqlite)
	dsn="${work}/padmark.db"
	;;
postgres)
	docker run -d --rm --name "$pg_container" -e POSTGRES_USER=padmark -e POSTGRES_PASSWORD=padmark \
		-e POSTGRES_DB=padmark -p 127.0.0.1::5432 postgres:18-alpine >/dev/null
	# The image's entrypoint restarts the server once after initdb; wait for the final one.
	until docker logs "$pg_container" 2>&1 | grep -q 'PostgreSQL init process complete'; do sleep 0.5; done
	until docker exec "$pg_container" pg_isready -U padmark -d padmark >/dev/null 2>&1; do sleep 0.5; done
	pg_port=$(docker port "$pg_container" 5432/tcp | head -1 | sed 's/.*://')
	dsn="postgres://padmark:padmark@127.0.0.1:${pg_port}/padmark?sslmode=disable"
	;;
*)
	echo "storage must be sqlite or postgres" >&2
	exit 2
	;;
esac

"$bin" serve --storage "$storage" --dsn "$dsn" --addr "127.0.0.1:${port}" --rate-limit 0 \
	--log-format text >"${work}/server.log" 2>&1 &
server_pid=$!
until curl -fsS "${base}/healthz" >/dev/null 2>&1; do sleep 0.2; done

# create <json-body> -> prints "<slug> <edit_code>"
create() {
	curl -fsS -X POST "${base}/notes" -H 'Content-Type: application/json' -H 'Accept: application/json' \
		--data-binary "$1" | jq -r '"\(.id) \(.edit_code)"'
}

# read_note <slug>: one JSON GET, exactly what an API client did in v0.1.6.
read_note() {
	curl -fsS "${base}/notes/$1" -H 'Accept: application/json' >/dev/null
}

note1_content=$'pmc2$p$fake is plain text that only looks like an envelope tag\n# Привет, мир 🌍 — ünïcödé\n\nPrice: $42, shell: `echo $HOME`\n\nSGVsbG8sIHBhZG1hcmsgdjAuMS42IHBsYWludGV4dCBub3Rl\n'
# Note 7's whole content is canonical standard base64 (36 decoded bytes): without the
# legacy tag it would be mistaken for raw legacy ciphertext.
note7_content='SGVsbG8sIHBhZG1hcmsgdjAuMS42IHBsYWludGV4dCBub3Rl'

n1=$(create "$(jq -n --arg c "$note1_content" '{title: "1 unicode and dollars", content: $c}')")
n2=$(create "$(jq -n '{slug: "my-custom_Slug-1", edit_code: "hunter2", title: "2 custom slug",
	content: "Custom slug, caller-chosen edit code."}')")
n3=$(create "$(jq -n '{title: "3 private", content: "private <b>plain</b> text", content_type: "text/plain",
	private: true}')")
n4=$(create "$(jq -n '{title: "4 burn after reading", content: "read me once", burn_after_reading: true}')")
# v0.1.6 has no expires_at on create: expiry is set by the first read of a burn note with a ttl.
n5=$(create "$(jq -n '{title: "5 far future expiry", content: "expires in ten years",
	burn_after_reading: true, ttl: 315360000}')")
n6=$(create "$(jq -n '{title: "6 already expired", content: "expired before the dump",
	burn_after_reading: true, ttl: 1}')")
n7=$(create "$(jq -n --arg c "$note7_content" '{title: "7 viewed once", content: $c}')")

read_note "${n5%% *}"
read_note "${n6%% *}"
read_note "${n7%% *}"
sleep 3 # note 6's 1 s burn timer runs out

kill "$server_pid"
wait "$server_pid" 2>/dev/null || true
server_pid=""

{
	echo "-- padmark v0.1.6 fixture (${storage}); generated by generate.sh, see README.md"
	echo "-- slug edit_code per note, in scenario order:"
	for n in "$n1" "$n2" "$n3" "$n4" "$n5" "$n6" "$n7"; do echo "--   $n"; done
} >"$out"

case $storage in
sqlite)
	sqlite3 "$dsn" .dump >>"$out"
	;;
postgres)
	# psql meta-commands (\restrict / \unrestrict) are stripped so the file runs as plain SQL.
	docker exec "$pg_container" pg_dump -U padmark -d padmark --inserts --no-owner --no-privileges |
		grep -v '^\\' >>"$out"
	;;
esac

echo "wrote $out" >&2
